let lookback_timespan = totimespan('${Lookback_days}');
let lookback_days_num = toreal(extract("([0-9]+)", 1, '${Lookback_days}'));
let scale_factor = 365.0 / lookback_days_num;
let subs    = split('${Subscription:csv}', ',');
let rgs     = split('${ResourceGroup:csv}', ',');
let regions = split('${Region:csv}', ',');
let meters  = split('${MeterName:csv}', ',');
RestrictedAzureCostData_EnrollmentLevel
| where Timestamp > ago(lookback_timespan)
| where MeterCategory == "Azure Cosmos DB" or MeterCategory has "Cosmos DB for PostgreSQL"
| where '${Subscription:csv}'  == '.*' or SubscriptionName in (subs)
| where '${ResourceGroup:csv}' == '.*' or ResourceGroup    in (rgs)
| where '${Region:csv}'        == '.*' or ResourceLocation in (regions)
| where '${MeterName:csv}'     == '.*' or MeterName        in (meters)
| extend CosmosDBName = tolower(tostring(split(ResourceId, "/")[-1]))
| extend ApiType = case(
    MeterSubCategory has "Mongo" or CosmosDBName has "mongo", "MongoDB",
    MeterSubCategory has "Cassandra" or CosmosDBName has "cassandra", "Cassandra",
    MeterSubCategory has "Gremlin" or CosmosDBName has "gremlin", "Gremlin",
    MeterSubCategory has "Table", "Table",
    MeterCategory has "PostgreSQL" or MeterSubCategory has "PostgreSQL", "PostgreSQL",
    "SQL")
| summarize TotalCost = sum(CostInBillingCurrency)

