| where '${MeterName:csv}'     == '.*' or MeterName        in (meters);
let current  = base | where Timestamp > ago(lookback_timespan)
                    | summarize CurrentCost = sum(CostInBillingCurrency);
let previous = base | where Timestamp > ago(2 * lookback_timespan) and Timestamp <= ago(lookback_timespan)
                    | summarize PreviousCost = sum(CostInBillingCurrency);
current  | extend dummy = 1
| join kind=inner (previous | extend dummy = 1) on dummy
| extend PctChange = iif(PreviousCost > 0, (CurrentCost - PreviousCost) / PreviousCost * 100, 0.0)
| project PctChange

